import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"升","description":"高島易斷 - 升","frontmatter":{"title":"升","description":"高島易斷 - 升"},"headers":[],"relativePath":"classics/takashima/046.md","filePath":"classics/takashima/046.md"}'),i={name:"classics/takashima/046.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h2 id="升-1" tabindex="-1">升 <a class="header-anchor" href="#升-1" aria-label="Permalink to “升”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>升：元亨。用見大人，勿恤，南征吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>卦象由《巽》升《坤》，故曰《升》。《巽》本“小亨”，“元”者，《坤》之“元”，得夫坤元之氣，故曰“元亨”。“大人”謂二，《巽》《傳》曰“利見”，此曰“用見”，謂不升則不得見，用升而後可見也，故曰“用見”。得見大人，則大人必相與同升，自可無恤。“南征”者，出幽入明之謂也。《巽》之往《坤》，《坤》之往《巽》，皆必歷於南，譬如日月之升，皆南征，而其降也，皆北行，故曰“南征吉”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>地中生木，升。君子以順德，積小以高大。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>地中生木，當其萌孽始生，藐乎小矣，及至蔽日干霄，其高大不可限量，蓋不知幾經歲月，得以積累而至此也。順德以《坤》為極，《巽》柔在下，《坤》順在上，由《巽》升《坤》，非積不能。君子法之，以順其德，積小高大，德必日新而日懋也。人以此而樹木者，君子即以此而樹德焉。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：得春生之氣，運途當日進日盛。</p><p>○　問功名：有指日高升之象。</p><p>○　問營商：積累錙銖，可漸成富饒巨室。</p><p>○　問戰徵：宜平地架列木梯，可以登高攻城。</p><p>○　問婚姻：順為婦德，有以妾作嫡之象。</p><p>○　問家宅：此宅初時低小，近將改造大廈。</p><p>○　問疾病：是肝木春旺之症，若不順氣寬養，勢將日積日重，頗為可危。</p><p>○　問貨價：有逐步騰貴之象。</p><p>○　問秋收：風雨調順，年穀豐登。</p><p>○　問行人：一路順風，且積蓄頗豐。</p><p>○　問六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《升》之始，為《巽》之主，《升》者下也，而允其升者上也，上允其升，則《升》之志遂矣。上互《震》，《震》雷出地，聲聞百里，有《升》之象；下升上允，志同道合，吉莫大焉。《晉》六三曰“眾允”，下為二陰所信；《升》初六曰“允升”，上為二陽所信。以陰信陰，悔亡而已，以陰信陽，乃得大吉。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：運途大順，求名求利，無不如志，大吉。</p><p>○　問功名：一舉成名，大吉。</p><p>○　問營商：貨價高升，大可獲利。</p><p>○　問戰徵：升高窺望，得識敵情，一戰可得勝也，大吉。</p><p>○　問婚姻：兩姓允合，大吉。</p><p>○　問家宅：有出谷遷喬之兆，吉。</p><p>○　問疾病：爻象本吉，於問病獨非吉兆，惟在下痢下陷等症，則吉。</p><p>○　問訟事：宜上控，吉。</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>縉紳某來，請佔氣運，筮得《升》之《泰》。</p><p>斷曰：卦象取“地中生木”，木得春氣，枝葉怒生，漸增漸大，猶人行運得時，漸入佳境之象也。今佔得初爻，是初運也。《升》者，自下升上，允者，我求而被允，《升》得其允，斯《升》之志遂，《升》之道行矣。運途得此，所求所謀，於名於利，無不“合志”，大吉之佔也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居《巽》之中，備剛中之德，即為“用見”之“大人”。初欲升五，必先歷二，以求孚於二也。古者求賢審官，得人則告諸宗廟，二既孚初之《升》，特為齋祓以進之。上互《震》，《震》為祭，故“用禴”。《巽》，孟夏之月，“禴”，夏祭，“用禴”者，取“柔以時升”之義也。“禴”，祭之薄者，然輸誠求升，雖薄亦孚，在誠不在物也，故“無咎”。《象傳》曰“有喜”，即《彖傳》所云“有慶”也。《萃》六二以柔應五之剛，《升》九二以剛應五之柔，其至誠感應，則一也，故爻象“用禴”同，“無咎”亦同。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：運途得中，必有喜事臨門。</p><p>○　問營商：商業全憑信實，有信賣買進出，無詐無虞，自能永遠，且可獲利。</p><p>○　問功名：定有泥金報喜。</p><p>○　問戰徵：出師必祭，信為兵家之要，得信則三軍一心，無戰不克矣。</p><p>○　問婚姻：二五交孚，陰陽合德，大喜。</p><p>○　問家宅：主有喜兆。</p><p>○　問疾病：宜禱。</p><p>○　問六甲：單月生男，雙月生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某來，請佔氣運，筮得《升》之《謙》。</p><p>斷曰：《升》者自下升上，有積小高大之象。今足下問氣運，佔得第二爻，二爻剛中，為卦中之大人。“孚”者，信也，得其信，不特上下交通，即鬼神亦能感格。爻象如此，知足下信誼素著，於朋友上下之間，無不交孚，故得“無咎”，且近日即有升騰喜兆。</p><p>明治二十九年，某貴顯來，為設立農工銀行，佔問成否，筮得《升》之《謙》。</p><p>斷曰：卦體《坤》上《巽》下，《坤》為財，為富，《巽》為商，為利。五行以我克者為財，《巽》木克《坤》土，土為財。《升》者，積小高大，有漸進漸長之象。今貴下佔問銀行生業，得第二爻，爻辭曰“孚”，孚者，信也，金銀貿易，最要在信。“利用”者，利於用也，《洪範·六府》“心曰利用”，即此旨也。據此爻辭，銀行必成，且有喜兆。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>《升》之三，《巽》之終，《坤》之始也，《坤》為虛，亦為邑，故曰“升虛邑”。《說文》：“虛，大邱。九夫為井，四井為邑，四邑為邱”。邱，謂之虛，《詩》“升彼虛矣”，虛，即墟也。墟為空曠高地，由井升邑，由邑升虛，可見“積小以高大”，歷試諸艱，勝任愉快，地日闢而日大，位日進而日高。《象傳》曰“無所疑”，信乎三之《升》，《升》之得其任矣。徵諸太王居岐，一年成邑，二年成都，三年五倍於初，爻所言升虛升邑，蓋謂此也。《升》卦爻象三、四、五三爻，皆隱指周室之事。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：目下運途恰好，漸進漸盛。</p><p>○　問營商：市廛謂之趁虛，言就虛地，會集貨物而成市邑，可見商業日盛也。</p><p>○　問功名：《升》本發達之象，初方“允”，二則“孚”，至三則已升而在上，可無疑也。</p><p>○　問戰徵：經此兵燹，城邑空虛，“升虛邑”，奪取空城矣。</p><p>○　問家宅：有前空虛，後富實之象。</p><p>○　問婚姻：“虛邑”，猶空房也，不吉。</p><p>○　問疾病：必是虛弱之症無疑。</p><p>○　問失物：不得。</p><p>○　問六甲：九三陽爻，生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治十六年，縉紳某任某縣令，將赴任，請佔任事吉凶，筮得《升》之《師》。</p><p>斷曰：“虛邑”，為凋敝之地，人煙寥落，治理殊難，非盤根錯節之才，未易勝任也。今貴下新授某邑知事，行將赴任，佔得此爻，以貴下練達之才，任此積衰之邑，必能治劇理繁，為人所難為，當有措之裕如，無容疑也。可為貴下信之矣。</p><p>明治廿八年五月，為開墾北海道十勝國利別原野，佔其成否，筮得《升》之《師》。</p><p>斷曰：爻辭與佔象，悉相符合，可謂深切詳明。曰“虛邑”，即荒土地，曰“升虛邑”，是闢荒土而成村落也。初則允其升，謂從事開墾者，志相合也；二則孚其升，謂從事開墾者，必“有喜”也；三則升已成矣。事雖難，可無疑也，其成必矣。</p><p>明治三十一年，佔司法省氣運，筮得《升》之《師》。</p><p>斷曰：《象》謂積小高大，凡風化之日趨日上，政教之日進日強，皆為《升》也。今佔司法省，欲改設公明之法律，為內地雜居之準備，得《升》卦三爻。夫有其邑而不治，謂之“虛邑”，有其法而不用，亦謂之虛法。茲者司法省，新頒法律，將實施之於內地，是升虛而作實也，此令一行，必無阻礙，無容疑慮焉。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>岐山為周發祥之地，太王遷之，文王康之，時告祭喬獄，岐山當必在其內也。蓋天子祭天地，諸侯祭其境內之山川。“亨於岐山”，岐山在周境內，周先王實主其祀焉。稱王者，追王之謂也。遷岐山之始，避狄而來，而積小高大，遂成為王業之基，吉何如也！《象傳》以“順事”釋之，蓋隱指文王服事之誠，有順德，無二心也。此周公不言之旨，合前後爻象觀之，而可知矣。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：事順適，吉而無咎。</p><p>○　問戰徵：古者禱戰，祈克於上帝，然後接敵，此即用享之義也。享而後戰，其必克矣，吉。</p><p>○　問營商：貨物之生也，多取于山林川穀之間。祭法，民之取財用者，必祭之。謂祭之可獲利也。吉。</p><p>○　問功名：“亨於岐山”，易侯而王，大吉之兆。</p><p>○　問家宅：宜祭告宅神，吉。</p><p>○　問疾病：宜禱。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>某商人來，請佔氣運，筮得《升》之《恆》。</p><p>斷曰：《升》卦諸爻，皆言升，惟二四不言升，其義並取於祭享，謂人慾升騰發達，必先求神明之保也。四爻辭曰，“王用亨於岐山”，岐山為太王避狄之地，浸熾浸昌，大啟爾宇，為周室王運發祥之始。今足下佔得此爻，知足下氣運通順，正如曉日東昇，逐步增高，財運亨通，其中雖由足下計劃之精，要亦有神助也。宜齋祓以禱之，吉。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五以《坤》德居中，位極其尊，《象傳》所稱“君子以順德，積小以高大”，惟五當之。“階”，天子之阼階也，升之於階，尊之至焉。然不正則為新莽，為曹操，其何能吉？古來必如大舜之有鰥在下，側陋明揚，以至命陟帝位，爻曰“貞吉”，《象》曰“大得志”，惟舜有之矣。而作《易》之旨，則隱指西伯方百里起，終受周命之事也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：平生志願，無不得遂，大吉之兆。</p><p>○　問功名：拾級而登，榮寵已極。</p><p>○　問營商：五為中數，凡營財之道，不宜過盈，以得中為吉，故曰“貞吉”。</p><p>○　問戰徵：凡攻城，必用梯階，所以升高也。城必可克，故吉。</p><p>○　問婚姻：五與二相應，爻曰“升階”，有攀結高親之象，故二曰“有喜”。</p><p>○　問疾病：《升》，增也，病不宜升，亂階厲階，皆非吉兆。</p><p>○　問訟事：訟本凶事，是謂禍階，升階則訟愈兇，何以得吉？</p><p>○　問失物：當就階墀間尋之。</p><p>○　問六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>某氏來，請佔其女氣運，筮得《升》之《井》。</p><p>斷曰：《升》者謂“柔以時升”，《升》得其時，是以吉也。人之氣運，亦以時行，得時則順，失時則逆，惟在當其可之謂時也。今足下佔問子女行運，想必為嫁娶之事也。《詩》詠迨吉，為婚姻之及時。階，上進也，“升階”，升而愈上也，是必有貴戚訂姻，上嫁之象，大吉。後聞此女，果嫁某縉紳。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上居《坤》之極，《升》至於上，《升》無可升矣。如日之升，朝而日出，晝而日中，暮而日入，“冥”，則昏暮也，《坤》為冥，故曰“冥升”。“不息”者，晝夜循環之謂也，今日月沒，明日復升，故曰“利於不息之貞”。《坤》曰“永貞”，即“不息之貞”也。在人之升，至上則祿位已盡，魂升魄散，歸入幽冥之域，凡生前富貴利達，消歸無有，惟此道德勳名，足以流傳於不息耳，故《象傳》以“消不富”釋之，此之謂也。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：好運已過，且待後運重來，可以得利。</p><p>○　問戰徵：有率軍夜進，誤入幽谷之象，利於息，待天明可出險也。</p><p>○　問營商：防有人財兩失之患。</p><p>○　問功名：《升》至於上，功名已顯，防身後蕭條。</p><p>○　問婚姻：恐不得偕老。</p><p>○　問家宅：宅運已過，勢必中落。</p><p>○　問疾病：大象不利，“冥升”者，魂升於天也。</p><p>○　問六甲：生女，恐不育。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十四年，佔國運，筮得《升》之《蠱》。</p><p>斷曰：論卦體，《坤》上《巽》下，由《巽》升《坤》，《升》至於六，《坤》位已終，無可再升矣。今佔國運，得《升》上爻，我國家自維新以來，一革舊政，悉效歐美之法，以為取彼之長，補我之短，以冀日進於富強也。當時使年輕子弟，遊學歐美，以習學其文學言語、政化風俗，三年學成歸國，即升為學士、博士之職，使之教授國內子弟。法非不善，意非不良，無如此輩遊學子弟，其於我國向時政教，本未諳練，即於外國教育，亦徒窺其皮毛，反以揚揚自得，蔑視老成。其間所謂進步者，如海軍陸軍，駿駿日上，亦自有可取，而極之教育之原，身心之本，終覺利不勝害，為可慨也。維新迄今，已二十餘年，《升》進地步，約計已到上爻。“冥升”者，為日已近暮，無可復升，其利在“不息之貞”。“不息”者，為去而復來，循環不息之謂也。蓋謂我國治運所關，凡新法之不善者，皆當反我舊政，以返為《升》，猶是日之沒而復升，晦而復明，即所謂“不息之貞也”。斯之謂“利”，斯之謂“貞”。</p>',114)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
